import 'package:flutter/material.dart' hide Text;
import '../i18n.dart';
import '../widgets/skeleton.dart';
import '../theme.dart';
import '../api_service.dart';

/// FR7 - Reporting.
/// Monthly sales and revenue summary, generated by the backend.
/// The bar chart is drawn with plain Flutter widgets, so no extra
/// charting package is needed.
class SalesReportScreen extends StatefulWidget {
  const SalesReportScreen({super.key});

  @override
  State<SalesReportScreen> createState() => _SalesReportScreenState();
}

class _SalesReportScreenState extends State<SalesReportScreen> {
  late Future<SalesReport> _reportFuture;
  int _months = 6;

  @override
  void initState() {
    super.initState();
    _reportFuture = ApiService.fetchSalesReport(months: _months);
  }

  Future<void> _refresh() async {
    setState(() {
      _reportFuture = ApiService.fetchSalesReport(months: _months);
    });
    await _reportFuture;
  }

  void _setMonths(int m) {
    setState(() {
      _months = m;
      _reportFuture = ApiService.fetchSalesReport(months: m);
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: TamuColors.background,
      appBar: AppBar(
        title: const Text('Sales Report'),
        actions: [
          IconButton(
            tooltip: tr('Refresh'),
            onPressed: _refresh,
            icon: const Icon(Icons.refresh),
          ),
        ],
      ),
      body: SafeArea(
        child: Center(
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 430),
            child: FutureBuilder<SalesReport>(
              future: _reportFuture,
              builder: (context, snapshot) {
                if (snapshot.connectionState == ConnectionState.waiting) {
                  return const SalesReportSkeleton();
                }
                if (snapshot.hasError) {
                  return _buildError(snapshot.error.toString());
                }
                final r = snapshot.data!;

                return RefreshIndicator(
                  onRefresh: _refresh,
                  child: ListView(
                    padding: const EdgeInsets.all(TamuSizes.pagePadding),
                    children: [
                      _buildHeadline(r),
                      const SizedBox(height: 16),
                      _buildSummaryGrid(r),
                      const SizedBox(height: 16),
                      if (r.pendingOrders > 0) ...[
                        _buildPendingCard(r),
                        const SizedBox(height: 16),
                      ],
                      _buildPeriodSelector(),
                      const SizedBox(height: 12),
                      _buildChart(r),
                      const SizedBox(height: 20),
                      _buildTopCrops(r),
                      const SizedBox(height: 24),
                    ],
                  ),
                );
              },
            ),
          ),
        ),
      ),
    );
  }

  Widget _buildHeadline(SalesReport r) {
    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(20),
      decoration: BoxDecoration(
        color: TamuColors.primary,
        borderRadius: BorderRadius.circular(TamuSizes.cardRadius),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Text('Total Revenue (completed orders)',
              style: TextStyle(fontSize: 14, color: Color(0xFFA5D6A7))),
          const SizedBox(height: 4),
          Text('RM ${r.totalRevenue.toStringAsFixed(2)}',
              style: const TextStyle(
                  fontSize: 34,
                  fontWeight: FontWeight.bold,
                  color: Colors.white)),
          const SizedBox(height: 6),
          Text('${r.farmerName}  ·  Tamparuli, Sabah',
              style: const TextStyle(fontSize: 13, color: Color(0xFFA5D6A7))),
        ],
      ),
    );
  }

  Widget _buildSummaryGrid(SalesReport r) {
    return GridView.count(
      crossAxisCount: 2,
      shrinkWrap: true,
      physics: const NeverScrollableScrollPhysics(),
      crossAxisSpacing: TamuSizes.gap,
      mainAxisSpacing: TamuSizes.gap,
      childAspectRatio: 1.5,
      children: [
        _statCard('Completed Orders', '${r.totalOrders}',
            Icons.check_circle_outline, TamuColors.primary),
        _statCard('Average Order', 'RM ${r.averageOrderValue.toStringAsFixed(2)}',
            Icons.equalizer_outlined, TamuColors.info),
        _statCard('Total Sold', '${r.totalKgSold} kg',
            Icons.scale_outlined, TamuColors.textSecondary),
        _statCard('This Month', 'RM ${r.thisMonthRevenue.toStringAsFixed(2)}',
            Icons.calendar_month_outlined, TamuColors.primary),
      ],
    );
  }

  Widget _statCard(String label, String value, IconData icon, Color color) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
      decoration: BoxDecoration(
        color: TamuColors.surface,
        borderRadius: BorderRadius.circular(TamuSizes.cardRadius),
        border: Border.all(color: TamuColors.border),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        mainAxisAlignment: MainAxisAlignment.center,
        mainAxisSize: MainAxisSize.min,
        children: [
          Icon(icon, size: 20, color: color),
          const SizedBox(height: 4),
          FittedBox(
            fit: BoxFit.scaleDown,
            alignment: Alignment.centerLeft,
            child: Text(value,
                maxLines: 1,
                style: TextStyle(
                    fontSize: 20, fontWeight: FontWeight.bold, color: color)),
          ),
          Text(label,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(
                  fontSize: 12, color: TamuColors.textSecondary)),
        ],
      ),
    );
  }

  Widget _buildPendingCard(SalesReport r) {
    return Container(
      padding: const EdgeInsets.all(TamuSizes.cardPadding),
      decoration: BoxDecoration(
        color: const Color(0xFFE3F2FD),
        borderRadius: BorderRadius.circular(TamuSizes.cardRadius),
        border: Border.all(color: TamuColors.info),
      ),
      child: Row(
        children: [
          const Icon(Icons.hourglass_bottom, color: TamuColors.info),
          const SizedBox(width: 10),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                const Text('Pending Revenue',
                    style:
                        TextStyle(fontSize: 16, fontWeight: FontWeight.bold)),
                Text(
                  'RM ${r.pendingRevenue.toStringAsFixed(2)} from '
                  '${r.pendingOrders} confirmed order'
                  '${r.pendingOrders == 1 ? "" : "s"} not yet completed',
                  style: const TextStyle(
                      fontSize: 14, color: TamuColors.textSecondary),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildPeriodSelector() {
    return Row(
      children: [
        const Text('Period',
            style: TextStyle(fontSize: 16, fontWeight: FontWeight.w600)),
        const Spacer(),
        for (final m in [3, 6, 12]) ...[
          Padding(
            padding: const EdgeInsets.only(left: 8),
            child: ChoiceChip(
              label: Text('$m mo',
                  style: TextStyle(
                      fontSize: 14,
                      fontWeight: FontWeight.w600,
                      color: _months == m
                          ? Colors.white
                          : TamuColors.textPrimary)),
              selected: _months == m,
              showCheckmark: false,
              selectedColor: TamuColors.primary,
              backgroundColor: Colors.white,
              side: BorderSide(
                  color:
                      _months == m ? TamuColors.primary : TamuColors.border),
              onSelected: (_) => _setMonths(m),
            ),
          ),
        ],
      ],
    );
  }

  /// Simple bar chart built from Containers - no charting package needed.
  Widget _buildChart(SalesReport r) {
    final maxRevenue = r.monthly.fold<double>(
        0, (max, m) => m.revenue > max ? m.revenue : max);

    return Container(
      padding: const EdgeInsets.all(TamuSizes.cardPadding),
      decoration: BoxDecoration(
        color: TamuColors.surface,
        borderRadius: BorderRadius.circular(TamuSizes.cardRadius),
        border: Border.all(color: TamuColors.border),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Text('Monthly Revenue',
              style: TextStyle(fontSize: 16, fontWeight: FontWeight.w600)),
          const SizedBox(height: 16),
          if (maxRevenue == 0)
            const Padding(
              padding: EdgeInsets.symmetric(vertical: 30),
              child: Center(
                child: Text('No completed sales in this period yet',
                    style: TextStyle(
                        fontSize: 14, color: TamuColors.textSecondary)),
              ),
            )
          else
            SizedBox(
              height: 170,
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.end,
                children: r.monthly.map((m) {
                  final ratio = maxRevenue == 0 ? 0.0 : m.revenue / maxRevenue;
                  return Expanded(
                    child: Padding(
                      padding: const EdgeInsets.symmetric(horizontal: 3),
                      child: Column(
                        mainAxisAlignment: MainAxisAlignment.end,
                        children: [
                          if (m.revenue > 0)
                            FittedBox(
                              fit: BoxFit.scaleDown,
                              child: Text(m.revenue.toStringAsFixed(0),
                                  style: const TextStyle(
                                      fontSize: 11,
                                      fontWeight: FontWeight.bold,
                                      color: TamuColors.primary)),
                            ),
                          const SizedBox(height: 4),
                          Container(
                            height: (110 * ratio).clamp(3.0, 110.0),
                            decoration: BoxDecoration(
                              color: m.revenue > 0
                                  ? TamuColors.primary
                                  : TamuColors.border,
                              borderRadius: const BorderRadius.vertical(
                                  top: Radius.circular(4)),
                            ),
                          ),
                          const SizedBox(height: 6),
                          FittedBox(
                            fit: BoxFit.scaleDown,
                            child: Text(
                              m.label.split(' ').first,
                              style: const TextStyle(
                                  fontSize: 11,
                                  color: TamuColors.textSecondary),
                            ),
                          ),
                        ],
                      ),
                    ),
                  );
                }).toList(),
              ),
            ),
        ],
      ),
    );
  }

  Widget _buildTopCrops(SalesReport r) {
    return Container(
      padding: const EdgeInsets.all(TamuSizes.cardPadding),
      decoration: BoxDecoration(
        color: TamuColors.surface,
        borderRadius: BorderRadius.circular(TamuSizes.cardRadius),
        border: Border.all(color: TamuColors.border),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Text('Top Selling Crops',
              style: TextStyle(fontSize: 16, fontWeight: FontWeight.w600)),
          const SizedBox(height: 12),
          if (r.topCrops.isEmpty)
            const Padding(
              padding: EdgeInsets.symmetric(vertical: 16),
              child: Center(
                child: Text('No completed sales yet',
                    style: TextStyle(
                        fontSize: 14, color: TamuColors.textSecondary)),
              ),
            )
          else
            ...r.topCrops.asMap().entries.map((entry) {
              final rank = entry.key + 1;
              final c = entry.value;
              return Padding(
                padding: const EdgeInsets.only(bottom: 10),
                child: Row(
                  children: [
                    Container(
                      width: 28,
                      height: 28,
                      decoration: BoxDecoration(
                        color: rank == 1
                            ? TamuColors.primary
                            : TamuColors.lightGreen,
                        borderRadius: BorderRadius.circular(14),
                      ),
                      child: Center(
                        child: Text('$rank',
                            style: TextStyle(
                                fontSize: 13,
                                fontWeight: FontWeight.bold,
                                color: rank == 1
                                    ? Colors.white
                                    : TamuColors.primary)),
                      ),
                    ),
                    const SizedBox(width: 10),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(c.productName,
                              style: const TextStyle(
                                  fontSize: 16, fontWeight: FontWeight.w600)),
                          Text(
                            '${formatUnitQuantity(c.quantity, c.unit)}  ·  ${c.orders} order'
                            '${c.orders == 1 ? "" : "s"}',
                            style: const TextStyle(
                                fontSize: 13,
                                color: TamuColors.textSecondary),
                          ),
                        ],
                      ),
                    ),
                    Text('RM ${c.revenue.toStringAsFixed(2)}',
                        style: const TextStyle(
                            fontSize: 16,
                            fontWeight: FontWeight.bold,
                            color: TamuColors.primary)),
                  ],
                ),
              );
            }),
        ],
      ),
    );
  }

  Widget _buildError(String msg) {
    return ListView(
      padding: const EdgeInsets.all(24),
      children: [
        const SizedBox(height: 40),
        const Icon(Icons.bar_chart, size: 56, color: TamuColors.textSecondary),
        const SizedBox(height: 12),
        const Text('Cannot load report',
            textAlign: TextAlign.center,
            style: TextStyle(fontSize: 18, fontWeight: FontWeight.w600)),
        const SizedBox(height: 12),
        Text(msg.replaceFirst('Exception: ', ''),
            textAlign: TextAlign.center,
            style: const TextStyle(fontSize: 13, color: TamuColors.danger)),
        const SizedBox(height: 16),
        ElevatedButton(onPressed: _refresh, child: const Text('Try Again')),
      ],
    );
  }
}
